    # Use O(min(n,m)) space DP for Levenshtein distance.
    # Ensure the shorter string is used for the inner loop to keep memory low.
    if len(a) < len(b):
        a, b = b, a  # make a the longer string
    n, m = len(a), len(b)
    # previous row for DP (size m+1)
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        ai = a[i - 1]
        for j in range(1, m + 1):
            if ai == b[j - 1]:
                cur[j] = prev[j - 1]
            else:
                cur[j] = 1 + min(prev[j], cur[j - 1], prev[j - 1])
        prev = cur
    return prev[m]
