def solve(tokens):
    stack = []
    for t in tokens:
        if t in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                res = a + b
            elif t == '-':
                res = a - b
            elif t == '*':
                res = a * b
            else:
                res = int(a / b)  # truncate toward zero
            stack.append(res)
        else:
            stack.append(int(t))
    return stack[-1] if stack else 0

