def solve(nums):
    n=len(nums)
    if n<=1:
        return nums[:]
    i=n-2
    while i>=0 and nums[i]>=nums[i+1]:
        i-=1
    if i==-1:
        return sorted(nums)
    j=n-1
    while nums[j]<=nums[i]:
        j-=1
    new=nums[:]
    new[i],new[j]=new[j],new[i]
    new[i+1:]=reversed(new[i+1:])
    return new

print(solve([]))
